@import url("https://unpkg.com/@catppuccin/highlightjs@1.0.0/css/catppuccin-variables.important.css");
:root .dark-theme {
  color-scheme: dark;
  --ctp-rosewater: #f5e0dc;
  --ctp-flamingo: #f2cdcd;
  --ctp-pink: #f5c2e7;
  --ctp-mauve: #cba6f7;
  --ctp-red: #f38ba8;
  --ctp-maroon: #eba0ac;
  --ctp-peach: #fab387;
  --ctp-yellow: #f9e2af;
  --ctp-green: #a6e3a1;
  --ctp-teal: #94e2d5;
  --ctp-sky: #89dceb;
  --ctp-sapphire: #74c7ec;
  --ctp-blue: #89b4fa;
  --ctp-lavender: #b4befe;
  --ctp-text: #cdd6f4;
  --ctp-subtext1: #bac2de;
  --ctp-subtext0: #a6adc8;
  --ctp-overlay2: #9399b2;
  --ctp-overlay1: #7f849c;
  --ctp-overlay0: #6c7086;
  --ctp-surface2: #585b70;
  --ctp-surface1: #45475a;
  --ctp-surface0: #313244;
  --ctp-base: #1e1e2e;
  --ctp-mantle: #181825;
  --ctp-crust: #11111b;
  --bard-color-neutral-90: #181825;
  --bard-color-on-selected-conversation-metadata-v2: #cdd6f4;
  --bard-color-surface-container: #181825;
  --bard-color-on-surface-opacity-38: #585b70 !important;
  --bard-color-surface-container-highest: #28283d;
  --bard-color-response-container-flipped-background: #313244;
  --bard-color-inverse-on-surface: #161622;
  --bard-color-sidenav-mobile-controls: #cdd6f4;
  --bard-color-main-container-background: #1e1e2e;
  --bard-color-main-container-background-rgb: 30, 30, 46;
  --bard-color-window-container-background: #1e1e2e;
  --bard-color-response-container-background: #1e1e2e;
  --bard-color-response-container-background-rgb: 30, 30, 46;
  --bard-color-onhover-conversation-metadata-button-v2: #45475a;
  --bard-color-selected-conversation-metadata-button-v2: rgba(203, 166, 247, 0.4);
  --bard-color-new-conversation-button: #313244;
  --bard-color-on-new-conversation-button: #cdd6f4;
  --bard-color-onhover-conversation-metadata-v2: #313244;
  --bard-color-sidenav-upgrade-button: #313244;
  --bard-color-form-field-placeholder: #a6adc8;
  --bard-color-discovery-carousel-background: #181825;
  --bard-color-discovery-carousel-icon: #cba6f7;
  --bard-color-example-prompt-background: #11111b;
  --bard-color-bard-mode-logo-prefix: #bac2de;
  --bard-color-neutral-96: #11111b;
